async function run() {
  const page = figma.root.children.find(p => p.id === "0:1" || p.name.includes("00"));
  if (!page) {
    console.log("Page 00 not found");
    return;
  }

  function findTexts(node, texts = []) {
    if (node.type === "TEXT") {
      texts.push({ id: node.id, name: node.name, characters: node.characters });
    }
    if ("children" in node) {
      for (const child of node.children) {
        findTexts(child, texts);
      }
    }
    return texts;
  }

  const texts = findTexts(page);
  console.log("Found texts:", JSON.stringify(texts, null, 2));
}
run();

(async () => {
  const page = figma.root.children.find(p => p.id === "0:1" || p.name.includes("00"));
  if (!page) return "Page 00 not found";

  function getStructure(node, depth = 0) {
    let result = "  ".repeat(depth) + `[${node.type}] ${node.name}`;
    if (node.type === "TEXT") {
      result += `: "${node.characters.replace(/\n/g, "\\n")}"`;
    }
    result += "\n";
    if ("children" in node && depth < 5) {
      for (const child of node.children) {
        result += getStructure(child, depth + 1);
      }
    }
    return result;
  }

  return getStructure(page);
})()

