(async () => {
  const p04 = figma.root.children.find(p => p.id === "1:4");
  const mediaNodes = {};

  function collectNodes(node) {
    if (node.type === "FRAME" || node.type === "COMPONENT" || node.type === "INSTANCE" || node.type === "GROUP") {
      mediaNodes[node.name] = { id: node.id, width: node.width, height: node.height };
    }
    if ("children" in node) {
      for (const child of node.children) {
        collectNodes(child);
      }
    }
  }

  collectNodes(p04);
  return mediaNodes;
})()

(async () => {
  const p02 = figma.root.children.find(p => p.id === "1:3");
  const nodes = {};

  function collect(node) {
    if (node.type === "COMPONENT" || node.type === "FRAME" || node.type === "INSTANCE") {
      nodes[node.name] = { id: node.id, type: node.type, width: node.width, height: node.height };
    }
    if ("children" in node) {
      for (const child of node.children) {
        collect(child);
      }
    }
  }

  collect(p02);
  return nodes;
})()

(async () => {
  const p02 = figma.root.children.find(p => p.id === "1:3");
  const button = p02.findOne(node => node.name === "Button" && node.type === "COMPONENT");
  const textField = p02.findOne(node => node.name === "Text Field" && node.type === "COMPONENT");

  function getPropDesc(node) {
    if (!node) return "not found";
    let desc = `[${node.type}] ${node.name}\n`;
    if ("children" in node) {
      for (const child of node.children) {
        desc += `  - [${child.type}] ${child.name}`;
        if (child.type === "TEXT") {
          desc += `: "${child.characters.replace(/\n/g, "\\n")}"`;
        }
        if (child.fills && child.fills.length > 0) {
          desc += ` fill:${JSON.stringify(child.fills[0])}`;
        }
        desc += "\n";
      }
    }
    return desc;
  }

  return {
    button: getPropDesc(button),
    textField: getPropDesc(textField)
  };
})()

