  const f3 = frames.find(f => f.name === "03_Home");
  const f4 = frames.find(f => f.name === "04_Menu");

  function dumpTree(node, depth = 0) {
    let s = "  ".repeat(depth) + `[${node.type}] ${node.name}\n`;
    if ("children" in node) {
      for (const child of node.children) {
        s += dumpTree(child, depth + 1);
      }
    }
    return s;
  }

  return {
    f1: dumpTree(f1),
    f2: dumpTree(f2),
    f3: dumpTree(f3),
    f4: dumpTree(f4)
  };
})()

