(async () => {
  const workspacePage = figma.root.children.find(p => p.id === "6:2" || p.name.includes("03"));
  const f1 = workspacePage.children.find(f => f.name === "01_Onboarding");
  const f2 = workspacePage.children.find(f => f.name === "02_Phone_Number");

  function getNames(node) {
    let res = [node.name];
    if ("children" in node) {
      for (const c of node.children) {
        res = res.concat(getNames(c));
      }
    }
    return res;
  }

  return {
    f1Names: getNames(f1),
    f2Names: getNames(f2)
  };
})()

(async () => {
  const workspacePage = figma.root.children.find(p => p.id === "6:2" || p.name.includes("03"));
  const frames = workspacePage.children.filter(c => c.type === "FRAME");

  const f1 = frames.find(f => f.name === "01_Onboarding");
  const f2 = frames.find(f => f.name === "02_Phone_Number");
  const f3 = frames.find(f => f.name === "03_Home");
  const f4 = frames.find(f => f.name === "04_Menu");

  function findNodeByName(root, name) {
    if (root.name === name) return root;
    if ("children" in root) {
      for (const child of root.children) {
        const found = findNodeByName(child, name);
        if (found) return found;
      }
    }
    return null;
  }

  const btnGetStarted01 = findNodeByName(f1, "Btn_Get_Started");
  const btnGetStarted02 = findNodeByName(f2, "Btn_Get_Started"); // find the first one or specifically the one in sheet
  const sheet02 = f2.findOne(n => n.name === "Sheet");
  const btnGetStarted02_Sheet = sheet02.findOne(n => n.name === "Btn_Get_Started");
  const btnCancel02 = findNodeByName(f2, "Btn_Cancel");
  const btnAvatar03 = findNodeByName(f3, "Btn_Avatar");
  const dismissZone04 = findNodeByName(f4, "Dismiss_Zone");

  btnGetStarted01.reactions = [{
    trigger: { type: "ON_CLICK" },
    actions: [{ type: "NODE", destinationId: f2.id, navigation: "NAVIGATE", transition: null }]
  }];

  btnGetStarted02_Sheet.reactions = [{
    trigger: { type: "ON_CLICK" },
    actions: [{ type: "NODE", destinationId: f3.id, navigation: "NAVIGATE", transition: null }]
  }];

  btnCancel02.reactions = [{
    trigger: { type: "ON_CLICK" },
    actions: [{ type: "NODE", destinationId: f1.id, navigation: "NAVIGATE", transition: null }]
  }];

  btnAvatar03.reactions = [{
    trigger: { type: "ON_CLICK" },
    actions: [{ type: "NODE", destinationId: f4.id, navigation: "NAVIGATE", transition: null }]
  }];

  dismissZone04.reactions = [{
    trigger: { type: "ON_CLICK" },
    actions: [{ type: "NODE", destinationId: f3.id, navigation: "NAVIGATE", transition: null }]
  }];

  return "Prototyping setup successful!";
})()

